package fetch

import "sync"

// Fetcher memoises the results of an expensive computation.
type Fetcher struct {
	compute func(string) int
	cache   map[string]int
	calls   int
}

// New returns a Fetcher that computes missing values with f.
func New(f func(string) int) *Fetcher {
	return &Fetcher{compute: f, cache: map[string]int{}}
}

// Get returns the value for k, computing it only the first time.
func (f *Fetcher) Get(k string) int {
	if v, ok := f.cache[k]; ok {
		return v
	}
	f.calls++
	v := f.compute(k)
	f.cache[k] = v
	return v
}

// Calls reports how many times compute has been called.
func (f *Fetcher) Calls() int { return f.calls }

// All returns the value for every key, fetching them concurrently.
func (f *Fetcher) All(keys []string) map[string]int {
	out := map[string]int{}
	var wg sync.WaitGroup
	for _, k := range keys {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			out[k] = f.Get(k)
		}(k)
	}
	wg.Wait()
	return out
}

