package fetch

import (
	"strconv"
	"sync"
	"testing"
	"time"
)

func slowLen(k string) int {
	time.Sleep(time.Millisecond)
	return len(k)
}

func TestGetMemoises(t *testing.T) {
	f := New(slowLen)
	if f.Get("abc") != 3 || f.Get("abc") != 3 {
		t.Fatal("Get")
	}
	if f.Calls() != 1 {
		t.Fatalf("Calls = %d, want 1", f.Calls())
	}
}

func TestComputeOncePerKeyUnderLoad(t *testing.T) {
	f := New(slowLen)
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if f.Get("same") != 4 {
				t.Error("wrong value")
			}
		}()
	}
	wg.Wait()
	if got := f.Calls(); got != 1 {
		t.Fatalf("compute ran %d times for one key, want 1", got)
	}
}

func TestAllReturnsEveryKeyOnce(t *testing.T) {
	f := New(slowLen)
	var keys []string
	for i := 0; i < 40; i++ {
		keys = append(keys, strconv.Itoa(i%10))
	}
	out := f.All(keys)
	if len(out) != 10 {
		t.Fatalf("All returned %d keys, want 10", len(out))
	}
	for k, v := range out {
		if v != len(k) {
			t.Fatalf("All[%q] = %d", k, v)
		}
	}
	if got := f.Calls(); got != 10 {
		t.Fatalf("compute ran %d times for 10 distinct keys, want 10", got)
	}
}

