package fetch

import (
	"strconv"
	"sync"
	"testing"
	"time"
)

func TestHiddenMixedLoad(t *testing.T) {
	f := New(func(k string) int { return len(k) * 2 })
	var keys []string
	for i := 0; i < 300; i++ {
		keys = append(keys, "k"+strconv.Itoa(i%25))
	}
	var wg sync.WaitGroup
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			out := f.All(keys)
			if len(out) != 25 {
				t.Errorf("All returned %d keys, want 25", len(out))
			}
			for k, v := range out {
				if v != len(k)*2 {
					t.Errorf("All[%q] = %d", k, v)
				}
			}
		}()
	}
	wg.Wait()
	if got := f.Calls(); got != 25 {
		t.Fatalf("compute ran %d times for 25 distinct keys, want 25", got)
	}
}

func TestHiddenDistinctKeysRunAtTheSameTime(t *testing.T) {
	f := New(func(k string) int {
		time.Sleep(300 * time.Millisecond)
		return len(k)
	})
	keys := []string{"a", "bb", "ccc", "dddd", "eeeee", "ffffff", "ggggggg", "hhhhhhhh"}
	start := time.Now()
	out := f.All(keys)
	el := time.Since(start)
	if len(out) != 8 {
		t.Fatalf("All returned %d keys", len(out))
	}
	// Eight independent computations of 300ms each: concurrent is ~300ms,
	// one lock held across the computation is 2.4s. The bar is 1.2s, so a
	// loaded machine still passes and a serialised cache still fails.
	if el > 1200*time.Millisecond {
		t.Fatalf("All over 8 distinct keys took %s: the computations are not running at the same time", el)
	}
}

func TestHiddenEmpty(t *testing.T) {
	f := New(func(k string) int { return 1 })
	if out := f.All(nil); len(out) != 0 {
		t.Fatalf("All(nil) = %v", out)
	}
	if f.Calls() != 0 {
		t.Fatal("All(nil) must not compute anything")
	}
}
